"""A64 instruction adapter."""

from __future__ import annotations

from pathlib import Path

from .html_transform import transform_instruction
from .model import Page
from .render import Renderer

# These are generated by Arm's own index stylesheets and are replaced by the
# site's own listing pages (or intentionally not published).
EXCLUDED_PAGES = {
    "index.html",
    "fpsimdindex.html",
    "sveindex.html",
    "mortlachindex.html",
    "encodingindex.html",
    "notice.html",
}


def instruction_files(a64_dir: str | Path) -> list[Path]:
    xhtml_dir = Path(a64_dir) / "xhtml"
    return sorted(
        path for path in xhtml_dir.glob("*.html") if path.name not in EXCLUDED_PAGES
    )


def build_instruction_pages(a64_dir: str | Path, renderer: Renderer, version: str) -> list[Page]:
    a64_dir = Path(a64_dir)
    pages: list[Page] = []
    for xhtml_path in instruction_files(a64_dir):
        stem = xhtml_path.stem
        xml_path = a64_dir / f"{stem}.xml"
        shared = stem == "shared_pseudocode"
        content_html, title, description = transform_instruction(
            xhtml_path,
            xml_path,
            shared_pseudocode=shared,
        )
        page = renderer.instruction_page(
            title=title,
            description=description,
            content_html=content_html,
            version=version,
        )
        page.path = f"latest_aarch64/{xhtml_path.name}"
        pages.append(page)
    return pages
